import json
from PIL import Image
P='/tmp/sci/pages/book/p-0%d.png'
crops={'cell':(30,(60,780,1947,2460)),'sun':(29,(0,1912,669,2481)),'lev':(33,(1000,175,1706,1340)),'cls':(42,(62,187,1750,2125)),'par':(45,(125,112,825,875)),'tab':(29,(194,194,719,950))}
def crop(k,i):
    pg,b=crops[k]; Image.open(P%pg).crop(b).save('/tmp/sci/bookfigs/%s.png'%i); return '/tmp/sci/bookfigs/%s.png'%i, 'ص'+str(pg).translate(str.maketrans('0123456789','٠١٢٣٤٥٦٧٨٩'))
def E(task,think,steps,answer,why,tip): return dict(task=task,think=think,steps=steps,answer=answer,why=why,tip=tip)
D=[]
def add(i,ex,ma,pg,q,fig=None,conflict=''):
    f,fp=(crop(fig,i) if fig else (None,None))
    D.append(dict(id=i,explain=ex,model_answer=ma,book_page_exact=pg,book_quote=q,book_fig=f,book_fig_page=fp,conflict=conflict))
add('s-004',E('المطلوب: نعرف أي صفة موروثة وأي صفة مكتسبة.','اسألي نفسك: هل أخذتها من أمي وأبي، أم تعلمتها بنفسي؟',['الموروثة: تنتقل من الآباء إلى الأبناء، مثل لون الشعر.','المكتسبة: نتعلمها بالتدريب والممارسة، مثل طريقة الحديث أمام الناس.','لون الشعر موروث، وطريقة الحديث مكتسبة.'],'إذن الجواب: ب) لون الشعر صفة موروثة وطريقة الحديث صفة مكتسبة. (وإذا جاء السؤال إكمالاً: الصفات الوراثية، وإذا جاء صح وخطأ: الوراثة انتقال الصفات من الآباء إلى الأبناء، صح.)','أ) غلط لأن الحديث نتعلمه. ج) معكوسة. د) غلط لأن لون الشعر لا نتعلمه. بعض الطفلات يظنن أن كل شيء يشبه الأم موروث.','الشكل يورث، والمهارة تُتعلَّم.'),'ب) لون الشعر صفة موروثة وطريقة الحديث صفة مكتسبة','ص٢٨–٢٩','الصفات الوراثية هي الصفات التي تنتقل من الآباء إلى الأبناء... أي سلوك أو مهارة يكتسبها الإنسان أو الحيوان بالتعلم والتدريب والممارسة.')
add('s-009',E('المطلوب: نعرف مستوى الرئة في تنظيم الجسم.','اسألي نفسك: الرئة جزء له وظيفة واحدة محددة، أم مجموعة أجزاء؟',['الترتيب: خلية، ثم نسيج، ثم عضو، ثم جهاز حيوي.','العضو تجتمع فيه الأنسجة ليقوم بوظيفة محددة.','الرئة تأخذ الهواء، فهي عضو. وتعمل مع أعضاء أخرى في الجهاز التنفسي.'],'إذن الجواب: ج) عضو.','أ) الخلية أصغر بكثير. ب) النسيج جزء من العضو. د) الجهاز الحيوي مجموعة أعضاء. يخطئ بعض الطفلات فيخترن الجهاز لأن الرئة مهمة.','خلية، نسيج، عضو، جهاز: درجات سلم.'),'ج) عضو','ص٣٣','الأنسجة تجتمع معًا لتكوّن عضوًا يقوم بوظيفة محددة. فالقلب مثلاً يقوم بضخ الدم.','lev')
add('s-014',E('المطلوب: نصحح الكلمة التي تحتها خط.','اسألي نفسك: ما أكبر مجموعة نضع فيها المخلوقات؟',['نرتب من الأكبر إلى الأصغر: المملكة، الشعبة، الطائفة...','الشعبة مجموعة أصغر من المملكة.','إذن الأكبر هي المملكة.'],'إذن الجواب: المملكة.','الشعبة تأتي بعد المملكة مباشرة، فتختلط على بعض الطفلات.','المملكة الكبيرة أولاً.'),'المملكة','ص٤٠ و ص٤٢','قسم العلماء الممالك إلى مجموعات أصغر تسمى شعبة.','cls')
add('s-021',E('المطلوب: نكتب اسم الجزء الذي يشير إليه كل سهم في الخلية النباتية.','اسألي نفسك: أي جزء يخزن الماء؟ وأي جزء صلب في الخارج؟',['السهم الأول يشير إلى الفجوة داخل الخلية: تخزن الماء والغذاء، وهي الفجوة العصارية.','السهم الثاني يشير إلى الجدار الخارجي الصلب: الجدار الخلوي.','(وفي أسئلة النماذج الأخرى: الفجوات، الجدار الخلوي، خلية نباتية لأن فيها فجوة وجدارًا وبلاستيدات.)'],'إذن الجواب: الأول الفجوة العصارية، والثاني الجدار الخلوي.','الغشاء الخلوي رقيق وداخل الجدار، فقد تخلطه الطفلة مع الجدار.','الفجوة تخزن، والجدار يحمي.'),'السهم الأول: الفجوة العصارية. السهم الثاني: الجدار الخلوي','ص٣٠–٣١','الفجوة العصارية: تركيب في الخلية يخزن الماء والغذاء والفضلات. جدار الخلية: تركيب صلب يدعم ويحمي الخلية النباتية.','cell')
add('s-023',E('المطلوب: نعرف وظيفة الحياة التي يقوم بها زهر عباد الشمس حين يميل نحو الضوء.','اسألي نفسك: ماذا يفعل المخلوق إذا تغيرت البيئة حوله؟',['الزهرة تميل نحو ضوء الشمس.','ميلها إجابة لتغير في البيئة.','هذه وظيفة الاستجابة، ويسمى الانتحاء الضوئي.'],'إذن الجواب: الاستجابة (الانتحاء الضوئي).','بعض الطفلات يكتبن النمو أو التغذية، لكن الميل نحو الضوء رد فعل.','النبات يلتفت للشمس: استجابة.'),'الاستجابة','ص٣٠','ويسمى نمو النباتات في اتجاه ضوء الشمس الانتحاء الضوئي.','sun')
add('s-034',E('المطلوب: اسم مجموعة أعضاء تعمل معًا.','اسألي نفسك: ما أكبر مستوى في تنظيم الجسم؟',['الأعضاء تتعاون لتقوم بوظائف الحياة.','هذه المجموعة تسمى جهازًا حيويًا.'],'إذن الجواب: ب) الجهاز الحيوي.','العضو واحد فقط. النسيج من خلايا. الخلية أصغر وحدة.','أعضاء تتعاون = جهاز.'),'ب) الجهاز الحيوي','ص٣٣','تعمل الأعضاء وتتآزر معًا لتكوّن جهازًا يقوم بوظائف محددة... ويسمى الجهاز الحيوي.','lev')
add('s-035',E('المطلوب: نعرف الجزء الذي يتحكم في الخلية.','اسألي نفسك: أي جزء يحمل الصفات الوراثية داخل النواة؟',['النواة تتحكم في أنشطة الخلية.','داخل النواة الكروموسوم يحمل الصفات الوراثية.','إجابة الأستاذة موضي هي الكروموسوم.'],'إذن الجواب كما قالت موضي: د) الكروموسوم.','النواة تبدو مناسبة لأنها تتحكم في الخلية، لذلك تخطئ بعض الطفلات.','الكروموسوم داخل النواة يحمل الصفات.'),'د) الكروموسوم','ص٣٠','النواة: تركيب يتحكم في جميع أنشطة الخلية. الكروموسوم: تركيب داخل النواة يحمل الصفات الوراثية.','cell','الكتاب يقول إن النواة هي التي تتحكم في جميع أنشطة الخلية، والكروموسوم يحمل الصفات الوراثية فقط؛ وإجابة موضي (الكروموسوم) تختلف عن ظاهر الكتاب. تُركت كما هي.')
add('s-037',E('المطلوب: المملكة التي تصنع كل أفرادها غذاءها.','اسألي نفسك: من تصنع طعامها بالشمس؟',['النباتات فيها بلاستيدات خضراء تصنع الغذاء.','الفطريات لا تصنع غذاءها.','الحيوانات تتغذى على غيرها.'],'إذن الجواب: د) النباتات.','الطلائعيات بعضها فقط يصنع غذاءه كالطحالب، فتخطئ الطفلة. كلمة "جميع" مهمة.','النبات مصنع غذائه.'),'د) النباتات','ص٤٦','تحتوي معظم خلايا النباتات على البلاستيدات الخضراء التي تتم فيها عملية البناء الضوئي لإنتاج الغذاء.')
add('s-038',E('المطلوب: المجموعة الأكثر تشابهًا.','اسألي نفسك: كلما قل العدد ماذا يحدث للتشابه؟',['كلما قل عدد الأفراد زاد التشابه.','أصغر مجموعة هي النوع.'],'إذن الجواب: ب) النوع.','المملكة والشعبة كبيرتان. الفصيلة أكبر من الجنس والنوع.','أصغر مجموعة = أكثر تشابه.'),'ب) النوع','ص٤٢','وأصغر مجموعتين في التصنيف هما مجموعة الجنس، والأصغر مجموعة النوع.','cls')
add('s-039',E('المطلوب: ما الذي تفعله كل المخلوقات الحية؟','اسألي نفسك: هل كلها تتحرك؟ هل كلها تتغير شكلاً؟',['كل المخلوقات الحية تحتاج الغذاء لتأخذ الطاقة.','النباتات لا تنتقل من مكانها.'],'إذن الجواب: ج) تحتاج إلى طاقة.','النباتات لا تنتقل، والنسيج ليس لكل مخلوق مثل البكتيريا.','كل حي يحتاج طاقة.'),'ج) تحتاج إلى طاقة','ص٢٩','تحصل المخلوقات الحية على الطاقة من الغذاء الذي تأكله.','tab')
add('s-044',E('المطلوب: نصحح الكلمة التي تحتها خط.','اسألي نفسك: أي مجموعة فيها صنف واحد؟',['في الجدول: النوع يحتوي على صنف واحد من المخلوقات الحية.','الشعبة تضم الطوائف.'],'إذن الجواب: النوع.','تخلط الطفلة الشعبة بالنوع لأن الاثنتين مجموعتان.','النوع صنف واحد.'),'النوع','ص٤٢','النوع: يحتوي على صنف واحد من المخلوقات الحية.','cls')
add('s-051',E('المطلوب: مملكة الطحالب.','اسألي نفسك: من الطلائعيات تصنع غذاءها؟',['الطلائعيات بعضها يصنع غذاءه مثل الطحالب.'],'إذن الجواب: مملكة الطلائعيات.','الطحالب تشبه النباتات فتخطئ الطفلة.','الطحالب من الطلائعيات.'),'مملكة الطلائعيات','ص٤٥','وبعض الطلائعيات تصنع غذاءها بنفسها، مثل الطحالب.','par')
add('s-054',E('المطلوب: اسم الأجزاء الخضراء في الخلية النباتية.','اسألي نفسك: ما مصنع الغذاء؟',['الأجزاء الخضراء مملوءة بالكلوروفيل.','اسمها البلاستيدات الخضراء.'],'إذن الجواب: البلاستيدات الخضراء. (وفي صح وخطأ: وجودها في جميع المخلوقات الحية، خطأ.)','لا توجد في الخلية الحيوانية.','الأخضر مصنع.'),'البلاستيدات الخضراء','ص٣٠','تحتوي معظم الخلايا النباتية على أجزاء خضراء تسمى البلاستيدات الخضراء.','cell')
add('s-056',E('المطلوب: المجموعة التي تضمها الشعبة.','اسألي نفسك: ماذا بعد الشعبة؟',['الشعبة تضم الطوائف.'],'إذن الجواب: الطائفة.','تخلط الطفلة بين الطائفة والرتبة.','شعبة ثم طائفة.'),'الطائفة','ص٤٢','وتضم الشعبة مجموعات أصغر تسمى الطوائف.','cls')
add('s-062',E('المطلوب: أصغر وحدة في بناء جسم المخلوق.','اسألي نفسك: ما الذي نبني منه الأنسجة؟',['الخلية أصغر وحدة.'],'إذن الجواب: أ) الخلية.','العضو والجهاز والنسيج أكبر.','الخلية الصغيرة.'),'أ) الخلية','ص٢٨','الخلية أصغر وحدة في بناء المخلوقات الحية.')
add('s-067',E('المطلوب: نعطي مثالاً لمملكة.','اسألي نفسك: ما أسماء الممالك؟',['العلماء قسموا المخلوقات إلى ست ممالك.','منها الحيوانات والنباتات.'],'إذن الجواب: الحيوانات / النباتات.','الفطريات والطلائعيات ممالك أيضًا.','ممالك: حيوانات ونباتات.'),'الحيوانات / النباتات','ص٤٠ و ص٤٦','الحيوانات: مخلوقات حية عديدة الخلايا.')
add('s-068',E('المطلوب: نصل كل مصطلح بتعريفه.','اسألي نفسك: ماذا يقول التعريف؟',['الهرم الغذائي: ج. الحساسية: د. الوراثة: و.','الجينات: تُركت بلا حرف.','البلاستيدات: ه. هرم الطاقة: أ. الهيكل الداخلي: ب.'],'إذن الجواب: الهرم الغذائي=ج، الحساسية=د، الوراثة=و، الجينات=بلا حرف، البلاستيدات الخضراء=ه، هرم الطاقة=أ، الهيكل الداخلي=ب.','الجينات لم يكن لها تعريف.','الوراثة انتقال الصفات.'),'كما في نص موضي','ص٢٨','الوراثة: انتقال الصفات الوراثية من الآباء إلى الأبناء.')
add('s-069',E('المطلوب: لماذا في بعض الخلايا ميتوكندريا كثيرة؟','اسألي نفسك: ما شغل الميتوكندريا؟',['تحرق الغذاء لتعطي الخلية طاقة.','كثرتها يعني حاجة لطاقة أكبر.'],'إذن الجواب: هذه الخلايا تحتاج طاقة كبيرة.','الطفلة قد تقول لأنها كبيرة.','ميتوكندريا كثيرة = طاقة كثيرة.'),'تحتاج الخلايا إلى طاقة كبيرة','ص٣٠','الميتوكندريا: يحرق الغذاء في هذا الجزء ليزود الخلية بالطاقة اللازمة.','cell')
add('s-072',E('المطلوب: مجموعة خلايا لها وظيفة واحدة.','اسألي نفسك: خلايا متشابهة؟',['النسيج خلايا متماثلة.'],'إذن الجواب: أ) النسيج.','العضو أنسجة.','خلايا متشابهة = نسيج.'),'أ) النسيج','ص٣٣','النسيج مجموعة من الخلايا المتماثلة تجتمع وتتعاون لتؤدي وظيفة محددة.','lev')
add('s-075',E('المطلوب: كلمة إنتاج أفراد جدد.','اسألي نفسك: ما اسم إنتاج مخلوقات جديدة؟',['التكاثر إنتاج مخلوقات جديدة.'],'إذن الجواب: التكاثر.','الوراثة انتقال الصفات.','تكاثر = أفراد جدد.'),'التكاثر','ص٢٨','التكاثر وهو إنتاج مخلوقات حية جديدة من النوع نفسه.')
